def F(no, ja, sel="-", kind="label", trig="view", **kw):
    """項目1つ。文字列は [日本語, ""] に包む（vi は翻訳のときに足す）。ex は [例の値, ""]"""
    d = {"no": no, "ja": ja, "vi": "", "sel": sel, "kind": kind, "trig": trig}
    for k, v in kw.items():
        if k in ("detail", "cond", "valid", "init", "demo_ok", "chk", "open", "ex") and isinstance(v, str):
            v = [v, ""]
        if k == "len" and isinstance(v, str) and not re.fullmatch(r"(文字列|整数) [0-9,〜]+|日付|日付（yyyy-mm-dd）", v):
            v = [v, ""]
        d[k] = v
    return d


