# =========================================================== 状態
def P(lst, *nos):
    """番号で項目を取り出す"""
    m = {d["no"]: d for d in lst}
    return [m[n] for n in nos]


def V(id, code, ja, url, items, setup="", note=None, full=True, wait=700):
    return {"id": id, "code": code, "state": [ja, ""], "url": url, "setup": (H + setup) if setup else "", "full": full, "wait": wait,
            "note": [note or "", ""], "items": items}


