def _X(lst, no, **kw):
    d = next(x for x in lst if x["no"] == no)
    for k, v in kw.items():
        if k == "vi":
            d["vi"] = v
        elif isinstance(d.get(k), list):
            d[k][1] = v
        else:
            raise KeyError((no, k))


def _L(lst, rows):
    for no, kw in rows:
        _X(lst, no, **kw)


